mapper.update:
UPDATE lubrication_logs
mold_id = #{moldId}, oil_level_percent = #{oilLevelPercent}, pressure_kpa = #{pressureKpa}, operator_id = #{operatorId}, operation_time = #{operationTime}, created_at = #{createdAt}, description = #{description},
WHERE id = #{id}

mapper.select:
SELECT l.id, l.mold_id, m.mold_code, m.name AS mold_name, l.oil_level_percent, l.pressure_kpa, l.operator_id, u.real_name AS operator_name, l.operation_time, l.created_at, l.description FROM lubrication_logs l LEFT JOIN molds m ON l.mold_id = m.id LEFT JOIN users u ON l.operator_id = u.id
AND l.mold_id = #{moldId}
AND ( m.name LIKE CONCAT('%', #{keyword}, '%') OR m.mold_code LIKE CONCAT('%', #{keyword}, '%') )
AND l.operator_id = #{operatorId}
AND l.operation_time >= #{startTime}
AND l.operation_time <= #{endTime}
ORDER BY l.operation_time DESC, l.created_at DESC

SELECT mold_id FROM lubrication_logs
WHERE operation_time >= #{since}
GROUP BY mold_id
HAVING

    MAX(oil_level_percent) > #{valueThreshold}
    MAX(oil_level_percent) >= #{valueThreshold}
    MAX(oil_level_percent) < #{valueThreshold}
    MAX(oil_level_percent) <= #{valueThreshold}
    MIN(oil_level_percent) > #{valueThreshold}
    MIN(oil_level_percent) >= #{valueThreshold}
    MIN(oil_level_percent) < #{valueThreshold}
    MIN(oil_level_percent) <= #{valueThreshold}
    AVG(oil_level_percent) > #{valueThreshold}
    AVG(oil_level_percent) >= #{valueThreshold}
    AVG(oil_level_percent) < #{valueThreshold}
    AVG(oil_level_percent) <= #{valueThreshold}
    MAX(pressure_kpa) > #{valueThreshold}
    MAX(pressure_kpa) >= #{valueThreshold}
    MAX(pressure_kpa) < #{valueThreshold}
    MAX(pressure_kpa) <= #{valueThreshold}
    MIN(pressure_kpa) > #{valueThreshold}
    MIN(pressure_kpa) >= #{valueThreshold}
    MIN(pressure_kpa) < #{valueThreshold}
    MIN(pressure_kpa) <= #{valueThreshold}
    AVG(pressure_kpa) > #{valueThreshold}
    AVG(pressure_kpa) >= #{valueThreshold}
    AVG(pressure_kpa) < #{valueThreshold}
    AVG(pressure_kpa) <= #{valueThreshold}
    1=0

SELECT mold_id FROM lubrication_logs
WHERE operation_time >= #{since}
AND

    oil_level_percent > #{valueThreshold}
    oil_level_percent >= #{valueThreshold}
    oil_level_percent < #{valueThreshold}
    oil_level_percent <= #{valueThreshold}
    pressure_kpa > #{valueThreshold}
    pressure_kpa >= #{valueThreshold}
    pressure_kpa < #{valueThreshold}
    pressure_kpa <= #{valueThreshold}
    1=0

GROUP BY mold_id
HAVING COUNT(1) >= #{countThreshold}
